const j = $json;
const s = j.student || {};

const currentStep = Math.max(
  0,
  Number(
    s.diagnostic_step ??
    j.diagnostic_step ??
    0
  ) || 0
);

const message = String(j.message || '').trim();
const history = Array.isArray(j.recent_messages)
  ? j.recent_messages
  : [];

const officialLevel =
  s.overall_level ||
  j.overall_level ||
  'PRE-A1';

const officialStatus = String(
  s.diagnostic_status ??
  j.diagnostic_status ??
  'pending'
).toLowerCase();

const normalized = message
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .toLowerCase()
  .trim();

function detectChoice(value) {
  const match = value.match(/(?:^|\b)([1-5])(?:\b|$)/);
  if (match) return Number(match[1]);

  if (value.includes('nunca estudei')) return 1;
  if (value.includes('algumas palavras') || value.includes('algumas expressoes')) return 2;
  if (value.includes('frases simples')) return 3;
  if (value.includes('dificuldade para falar') || value.includes('pronuncia')) return 4;
  if (value.includes('mais fluencia') || value.includes('conversar em ingles')) return 5;

  return null;
}

const selfAssessmentChoice =
  currentStep === 1
    ? detectChoice(normalized)
    : null;

const prompt = `
Você é Emma, avaliadora e professora de inglês do RS English.

Você está conduzindo um DIAGNÓSTICO INICIAL ADAPTATIVO, alinhado aos descritores do QECR/CEFR.

IMPORTANTE:
- Este é um diagnóstico pedagógico e uma estimativa de nível, não uma certificação oficial.
- Avalie evidências de uso da língua; não classifique apenas pela autoavaliação.
- Use descritores do tipo "é capaz de..." (can do).
- Considere recepção, produção e interação.
- Considere precisão gramatical, amplitude lexical, fluência, coerência e compreensão.
- Para pronúncia, use evidência de áudio. Não diagnostique sons específicos apenas pela transcrição.
- Não repita uma pergunta já respondida.
- Faça apenas uma pergunta ou tarefa por vez.
- Não envie duas versões da mesma pergunta em português e inglês, salvo quando o aluno pedir tradução ou demonstrar bloqueio.

DADOS DO ALUNO

Nome:
${s.name || j.name || 'Aluno'}

Status atual do diagnóstico:
${officialStatus}

Nível já registrado:
${officialLevel}

Etapa atual:
${currentStep}

Mensagem atual:
${message}

Opção de autoavaliação detectada nesta mensagem:
${selfAssessmentChoice ?? 'não aplicável'}

Histórico recente:
${JSON.stringify(history)}

ESCALA QECR/CEFR PARA ORIENTAÇÃO

PRE-A1:
- reconhece palavras, expressões muito frequentes e fórmulas básicas;
- ainda depende de modelos, opções e apoio intenso.

A1:
- usa expressões simples sobre dados pessoais, rotina e necessidades imediatas;
- interage de modo básico com apoio e ritmo lento.

A2:
- comunica-se em tarefas simples e rotineiras;
- descreve de forma simples experiências, ambiente e necessidades.

B1:
- compreende os pontos principais de temas familiares;
- produz discurso simples e conectado;
- relata experiências e explica brevemente opiniões e planos.

B2:
- interage com espontaneidade razoável;
- produz texto claro e detalhado;
- sustenta pontos de vista com razões e exemplos.

C1:
- usa a língua com flexibilidade e eficácia;
- produz discurso claro, bem estruturado e detalhado;
- compreende significados implícitos em textos e falas complexas.

C2:
- compreende praticamente tudo com facilidade;
- resume e reconstrói informações de várias fontes;
- expressa-se com grande precisão, naturalidade e controle de nuances.

ETAPAS DO DIAGNÓSTICO

ETAPA 0 — ACOLHIMENTO E AUTOAVALIAÇÃO

Envie esta pergunta, sem acrescentar outra tarefa:

"Olá! Eu sou a Emma, sua professora de inglês. 😊

Vou adaptar nosso diagnóstico ao que você já consegue fazer.

Qual opção combina mais com você?

1. Nunca estudei inglês
2. Sei algumas palavras e expressões
3. Consigo formar frases simples
4. Compreendo textos e frases, mas tenho dificuldade para falar ou pronunciar
5. Consigo ler, entender e conversar; quero desenvolver mais fluência"

Nesta etapa:
- complete=false
- next_step=1
- não tente classificar definitivamente.

ETAPA 1 — INTERPRETAR A AUTOAVALIAÇÃO E INICIAR A AMOSTRA

Interprete respostas numéricas, frases curtas ou o texto completo da opção.

Opção 1:
- faixa provisória PRE-A1;
- português com inglês muito curto;
- faça uma tarefa de reconhecimento com alternativas.

Opção 2:
- faixa provisória A1;
- português como apoio;
- peça uma resposta pessoal muito curta em inglês, com modelo.

Opção 3:
- faixa provisória A2;
- continue em inglês simples;
- peça 1 ou 2 frases sobre rotina, trabalho ou estudo;
- não traduza automaticamente.

Opção 4:
- faixa provisória B1;
- continue em inglês simples;
- peça uma resposta de 2 ou 3 frases;
- informe que pode escrever "translate" se precisar;
- planeje solicitar um áudio em etapa posterior.

Opção 5:
- faixa provisória B2;
- continue somente em inglês;
- peça uma resposta aberta com opinião, razão e exemplo.

Se a opção não estiver clara:
- não diga que houve erro técnico;
- peça apenas que responda com um número de 1 a 5;
- não reinicie todo o diagnóstico.

ETAPA 2 — PRODUÇÃO E INTERAÇÃO SOBRE TEMA FAMILIAR

Adapte a tarefa à faixa provisória.

PRE-A1/A1:
- dados pessoais, rotina ou preferência;
- modelo curto quando necessário.

A2:
- peça 2 frases conectadas sobre rotina, trabalho ou estudo.

B1:
- peça para relatar uma experiência recente e dizer por que foi importante.

B2+:
- peça opinião com justificativa e exemplo.

Avalie:
- compreensão da pergunta;
- adequação da resposta;
- vocabulário;
- estrutura das frases;
- capacidade de manter interação.

ETAPA 3 — CONTROLE TEMPORAL E COERÊNCIA

PRE-A1/A1:
- presente simples ou sequência muito curta.

A2:
- pergunte sobre ontem ou o último fim de semana.

B1:
- peça narrativa curta no passado com começo, meio e fim.

B2+:
- peça comparação entre duas experiências ou explique uma mudança ao longo do tempo.

Avalie:
- tempos verbais;
- conectores;
- coerência;
- extensão e independência da produção.

ETAPA 4 — OPINIÃO, PLANO E AMOSTRA ORAL

PRE-A1/A1:
- frase curta sobre gosto ou plano, com modelo.

A2:
- plano para o próximo fim de semana e uma razão.

B1:
- opinião sobre tema familiar, com razão e exemplo.

B2+:
- posição argumentada, incluindo vantagem, desvantagem ou contraponto.

Se a mensagem atual não for áudio:
- peça uma resposta de áudio curta, de 20 a 40 segundos;
- explique que o áudio ajuda a observar fluência e inteligibilidade;
- permita texto caso a pessoa não possa enviar áudio.

Se a mensagem atual for áudio:
- considere a amostra oral;
- não invente problemas fonéticos;
- avalie apenas fluência geral, inteligibilidade e organização percebidas pela transcrição e metadados disponíveis.

ETAPA 5 — DEVOLUTIVA FINAL

Conclua somente após considerar as respostas anteriores.

A reply deve conter:
- "Nível estimado pelo QECR: X";
- uma explicação curta baseada em capacidades observadas;
- 2 pontos fortes;
- 2 ou 3 prioridades;
- evidências observadas em linguagem simples;
- limitações da estimativa, especialmente se não houve áudio;
- plano inicial de 28 dias;
- primeira atividade;
- aviso de que o nível será refinado com novas interações.

Nunca diga:
- "em breve enviaremos";
- "aguarde o resultado";
- "não consegui interpretar";
- "tente novamente do início".

REGRAS DE IDIOMA

PRE-A1/A1:
- explicações em português;
- inglês curto e progressivo.

A2:
- inglês simples;
- português só para correção ou bloqueio.

B1:
- conversa principalmente em inglês;
- português apenas quando solicitado ou para explicar correção relevante.

B2/C1/C2:
- conversa em inglês;
- sem tradução automática.

SAÍDA OBRIGATÓRIA

Retorne SOMENTE um objeto JSON válido, sem markdown e sem texto antes ou depois:

{
  "reply": "",
  "current_step": ${currentStep},
  "next_step": ${Math.min(currentStep + 1, 5)},
  "complete": false,
  "self_assessment_option": ${selfAssessmentChoice ?? 'null'},
  "provisional_band": "",
  "estimated_level": "A1",
  "confidence": 0,
  "language_mode": "adaptive",
  "translation_on_request": true,
  "audio_sample_received": ${j.is_audio === true || j.message_type === 'audio'},
  "scores": {
    "reception": 0,
    "interaction": 0,
    "production": 0,
    "grammar": 0,
    "vocabulary": 0,
    "fluency": 0,
    "coherence": 0,
    "pronunciation": null
  },
  "cefr_evidence": [
    {
      "activity": "",
      "descriptor": "",
      "observed": false,
      "evidence": ""
    }
  ],
  "strengths": [],
  "weaknesses": [],
  "recommendations": [],
  "feedback": "",
  "corrections": [],
  "study_plan": {
    "goal": "",
    "duration_days": 28,
    "weekly_minutes": 100,
    "focus": [],
    "week_1": [],
    "week_2": [],
    "week_3": [],
    "week_4": []
  },
  "first_activity": {
    "title": "",
    "instruction": ""
  }
}

CONTROLE DA ETAPA

- Se current_step for 0, next_step deve ser 1.
- Se current_step for 1, next_step deve ser 2.
- Se current_step for 2, next_step deve ser 3.
- Se current_step for 3, next_step deve ser 4.
- Se current_step for 4, next_step deve ser 5.
- Se current_step for 5, complete deve ser true e next_step deve permanecer 5.
- Nunca volte para uma etapa anterior.
- Nunca repita a mesma pergunta do histórico.
`.trim();

return [{
  json: {
    ...j,
    diagnostic_prompt: prompt,
    diagnostic_current_step: currentStep,
    detected_self_assessment_option: selfAssessmentChoice
  }
}];

const response = $json;

let text = response.output_text;

if (!text && Array.isArray(response.output)) {
  const parts = [];

  for (const item of response.output) {
    for (const content of item.content ?? []) {
      if (typeof content.text === 'string') {
        parts.push(content.text);
      }
    }
  }

  text = parts.join('\n');
}

text = String(text ?? '')
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/```$/i, '')
  .trim();

const source = $('Montar Prompt Diagnóstico1').item.json;
const currentStep = Math.max(
  0,
  Number(
    source.diagnostic_current_step ??
    source.student?.diagnostic_step ??
    source.diagnostic_step ??
    0
  ) || 0
);

const message = String(source.message || '').trim();
const normalized = message
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .toLowerCase()
  .trim();

function detectChoice(value) {
  const match = value.match(/(?:^|\b)([1-5])(?:\b|$)/);
  if (match) return Number(match[1]);

  if (value.includes('nunca estudei')) return 1;
  if (value.includes('algumas palavras') || value.includes('algumas expressoes')) return 2;
  if (value.includes('frases simples')) return 3;
  if (value.includes('dificuldade para falar') || value.includes('pronuncia')) return 4;
  if (value.includes('mais fluencia') || value.includes('conversar em ingles')) return 5;

  return null;
}

function extractJson(value) {
  if (!value) return null;

  try {
    return JSON.parse(value);
  } catch (_) {}

  const start = value.indexOf('{');
  const end = value.lastIndexOf('}');

  if (start >= 0 && end > start) {
    try {
      return JSON.parse(value.slice(start, end + 1));
    } catch (_) {}
  }

  return null;
}

function profileForChoice(choice) {
  const profiles = {
    1: {
      level: 'PRE-A1',
      band: 'PRE-A1',
      languageMode: 'portuguese',
      reply: `Perfeito. Vamos começar com calma e bastante apoio em português.

Qual expressão significa “Meu nome é...”?

A. Good morning
B. My name is...
C. Thank you`
    },
    2: {
      level: 'A1',
      band: 'A1 inicial',
      languageMode: 'portuguese_support',
      reply: `Ótimo. Vamos usar frases curtas em inglês.

Complete o modelo:

“My name is ____ and I live in ____.”`
    },
    3: {
      level: 'A2',
      band: 'A1/A2',
      languageMode: 'simple_english',
      reply: `Great! Let's continue in simple English.

Tell me what you do during a normal day. Write one or two sentences.

If you need help, type “translate”.`
    },
    4: {
      level: 'B1',
      band: 'A2/B1',
      languageMode: 'simple_english',
      reply: `Great! Let's continue in English.

Tell me about something you are learning or working on now. Write two or three sentences.

If you need help, type “translate”.`
    },
    5: {
      level: 'B2',
      band: 'B1/B2',
      languageMode: 'english_only',
      reply: `Great! We'll continue completely in English.

Tell me about a goal you have for this year, why it matters to you, and one challenge you expect to face.`
    }
  };

  return profiles[choice] || null;
}

function deterministicFallback(step) {
  const choice = detectChoice(normalized);

  if (step === 0) {
    return {
      reply: `Olá! Eu sou a Emma, sua professora de inglês. 😊

Vou adaptar nosso diagnóstico ao que você já consegue fazer.

Qual opção combina mais com você?

1. Nunca estudei inglês
2. Sei algumas palavras e expressões
3. Consigo formar frases simples
4. Compreendo textos e frases, mas tenho dificuldade para falar ou pronunciar
5. Consigo ler, entender e conversar; quero desenvolver mais fluência`,
      self_assessment_option: null,
      provisional_band: '',
      estimated_level: 'PRE-A1',
      language_mode: 'adaptive',
      translation_on_request: true
    };
  }

  if (step === 1) {
    const profile = profileForChoice(choice);

    if (profile) {
      return {
        reply: profile.reply,
        self_assessment_option: choice,
        provisional_band: profile.band,
        estimated_level: profile.level,
        language_mode: profile.languageMode,
        translation_on_request: choice !== 5
      };
    }

    return {
      reply: `Para eu adaptar o diagnóstico, responda somente com um número de 1 a 5.

1. Nunca estudei inglês
2. Sei algumas palavras e expressões
3. Consigo formar frases simples
4. Compreendo, mas tenho dificuldade para falar
5. Consigo conversar e quero desenvolver fluência`,
      self_assessment_option: null,
      provisional_band: '',
      estimated_level: 'PRE-A1',
      language_mode: 'adaptive',
      translation_on_request: true,
      keep_step: true
    };
  }

  if (step === 2) {
    return {
      reply: `Let's talk about your routine.

What do you usually do in the morning?

You can answer with one or two sentences.`,
      estimated_level: source.student?.estimated_level || 'A1',
      language_mode: 'simple_english',
      translation_on_request: true
    };
  }

  if (step === 3) {
    return {
      reply: `Tell me about something you did yesterday or last weekend.

Try to explain what happened in two or three sentences.`,
      estimated_level: source.student?.estimated_level || 'A2',
      language_mode: 'simple_english',
      translation_on_request: true
    };
  }

  if (step === 4) {
    return {
      reply: `Please send a short audio, between 20 and 40 seconds, answering this question:

What is one goal you have for the next few months, and why is it important to you?

If you cannot send audio now, you may answer in text.`,
      estimated_level: source.student?.estimated_level || 'A2',
      language_mode: 'simple_english',
      translation_on_request: true
    };
  }

  return {
    reply: `Concluímos esta etapa do diagnóstico.

Seu nível estimado pelo QECR será tratado como provisório até termos mais amostras de texto e áudio.

Pontos observados:
• Você participou das tarefas propostas.
• Você conseguiu produzir respostas em inglês.

Prioridades iniciais:
• ampliar vocabulário;
• melhorar a organização das frases;
• praticar conversação com regularidade.

Primeira atividade:
Envie um áudio curto se apresentando e falando sobre sua rotina.

Seu nível será refinado conforme novas interações forem registradas.`,
    estimated_level:
      source.student?.estimated_level ||
      source.student?.overall_level ||
      'A1',
    language_mode: 'adaptive',
    translation_on_request: true,
    confidence: 35
  };
}

let diagnostic = extractJson(text);
const parsedSuccessfully = diagnostic !== null;

if (!diagnostic || typeof diagnostic !== 'object') {
  diagnostic = deterministicFallback(currentStep);
}

const allowedLevels = [
  'PRE-A1',
  'A1',
  'A2',
  'B1',
  'B2',
  'C1',
  'C2'
];

let estimatedLevel = String(
  diagnostic.estimated_level ||
  source.student?.estimated_level ||
  source.student?.overall_level ||
  'A1'
).toUpperCase();

if (!allowedLevels.includes(estimatedLevel)) {
  estimatedLevel = 'A1';
}

const detectedChoice =
  diagnostic.self_assessment_option ??
  source.detected_self_assessment_option ??
  (currentStep === 1 ? detectChoice(normalized) : null);

diagnostic.current_step = currentStep;
diagnostic.estimated_level = estimatedLevel;
diagnostic.self_assessment_option =
  detectedChoice === null || detectedChoice === undefined
    ? null
    : Number(detectedChoice);

if (currentStep === 1 && diagnostic.keep_step === true) {
  diagnostic.complete = false;
  diagnostic.next_step = 1;
} else if (currentStep >= 5) {
  diagnostic.complete = true;
  diagnostic.next_step = 5;
} else {
  diagnostic.complete = false;

  const proposed = Number(diagnostic.next_step);
  diagnostic.next_step =
    Number.isFinite(proposed) && proposed > currentStep
      ? Math.min(proposed, 5)
      : currentStep + 1;
}

delete diagnostic.keep_step;

diagnostic.confidence = Math.max(
  0,
  Math.min(100, Number(diagnostic.confidence ?? (parsedSuccessfully ? 55 : 25)) || 0)
);

diagnostic.audio_sample_received =
  Boolean(
    diagnostic.audio_sample_received ??
    source.is_audio === true ??
    source.message_type === 'audio'
  );

for (const key of [
  'strengths',
  'weaknesses',
  'recommendations',
  'corrections',
  'cefr_evidence'
]) {
  if (!Array.isArray(diagnostic[key])) {
    diagnostic[key] = [];
  }
}

if (!diagnostic.scores || typeof diagnostic.scores !== 'object') {
  diagnostic.scores = {};
}

if (!diagnostic.study_plan || typeof diagnostic.study_plan !== 'object') {
  diagnostic.study_plan = {};
}

if (!diagnostic.first_activity || typeof diagnostic.first_activity !== 'object') {
  diagnostic.first_activity = {};
}

const recentMessages = Array.isArray(source.recent_messages)
  ? source.recent_messages
  : [];

const lastTeacherMessage = [...recentMessages]
  .reverse()
  .find(item => String(item.role || '').toLowerCase() === 'teacher');

function normalizeForCompare(value) {
  return String(value || '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/\s+/g, ' ')
    .trim();
}

if (
  lastTeacherMessage &&
  normalizeForCompare(lastTeacherMessage.content) ===
    normalizeForCompare(diagnostic.reply)
) {
  const replacement = deterministicFallback(
    Math.min(currentStep + 1, 5)
  );

  diagnostic.reply = replacement.reply;
}

if (!String(diagnostic.reply || '').trim()) {
  diagnostic.reply = deterministicFallback(currentStep).reply;
}

if (diagnostic.complete) {
  const forbidden = [
    'em breve enviaremos',
    'depois enviaremos',
    'aguarde o resultado',
    'nao consegui interpretar',
    'não consegui interpretar'
  ];

  const normalizedReply = normalizeForCompare(diagnostic.reply);
  const invalidFinal =
    String(diagnostic.reply).length < 160 ||
    forbidden.some(term => normalizedReply.includes(normalizeForCompare(term)));

  if (invalidFinal) {
    const level = diagnostic.estimated_level || 'A1';
    const strengths = diagnostic.strengths.slice(0, 2);
    const weaknesses = diagnostic.weaknesses.slice(0, 3);
    const recommendations = diagnostic.recommendations.slice(0, 3);

    diagnostic.reply = [
      `Concluímos seu diagnóstico inicial.`,
      ``,
      `Nível estimado pelo QECR: ${level}.`,
      ``,
      `Esta é uma estimativa pedagógica baseada nas respostas registradas e será refinada com novas interações${diagnostic.audio_sample_received ? '.' : ' e com uma futura amostra de áudio.'}`,
      ``,
      `Pontos fortes:`,
      ...(strengths.length
        ? strengths.map(item => `• ${item}`)
        : [
            `• Participação nas tarefas propostas`,
            `• Capacidade de produzir respostas em inglês`
          ]),
      ``,
      `Prioridades:`,
      ...(weaknesses.length
        ? weaknesses.map(item => `• ${item}`)
        : [
            `• Ampliar vocabulário`,
            `• Organizar frases com mais segurança`,
            `• Desenvolver fluência na conversação`
          ]),
      ``,
      `Plano inicial de 28 dias:`,
      ...(recommendations.length
        ? recommendations.map(item => `• ${item}`)
        : [
            `• prática curta de conversação`,
            `• revisão dos erros recorrentes`,
            `• vocabulário ligado à rotina e aos objetivos`
          ]),
      ``,
      `Primeira atividade:`,
      diagnostic.first_activity?.instruction ||
        `Envie um áudio curto se apresentando e falando sobre sua rotina.`
    ].join('\n');
  }
}

return [{
  json: {
    ...source,
    diagnostic,
    teacher_message: String(diagnostic.reply || '').trim(),
